  ASSERT_EQ(gateway_process_session_future_watches_at(
                std::numeric_limits<uint64_t>::max()),
            1);

  ASSERT_EQ(gateway_session_future_watch_count(), 0);
  ASSERT_EQ(vm_owner_future_state(future_id), VM_OWNER_FUTURE_UNKNOWN);
