  ASSERT_EQ(vm_owner_drain_main_tasks(8), 0);
  ASSERT_TRUE(gateway_dispatch_message_for_test(
      replacement_fd,
      R"({"type":"data","cid":"gw-test-reliable-reconnect","ingress_id":"reconnect-stream","ingress_seq":2,"data":{"cmd":"second"}})"));
